text:
{
  "title_novice": "Что ГИС должна сказать о разрезе",
  "summary": [
    {
      "text": "Данные геофизических исследований скважин (ГИС) дают не один ответ, а набор выводов о разрезе.",
      "claims": ["c1"]
    },
    {
      "text": "Из них строят литологический разрез, находят коллекторы, оценивают их насыщение, толщину, пористость, проницаемость и глинистость.",
      "claims": ["c1", "c2", "c3", "c4"]
    },
    {
      "text": "В эксплуатационных скважинах по этим данным определяют, как смещаются водонефтяной контакт (ВНК) и газожидкостный контакт (ГЖК) при разработке.",
      "claims": ["c5", "c6"]
    }
  ],
  "claims": [
    {
      "key": "c1",
      "text": "Данные ГИС из поисковых, разведочных и эксплуатационных скважин используют для построения литологического разреза скважины.",
      "kind": "observation",
      "unit_id": "u-090-46f1de",
      "page": 90,
      "quote": "Данные геофизических исследований поисковых, разведочных и эксплуатационных скважин на нефть и газ используются для составления литологического разреза скважины",
      "numbers": [],
      "question": null
    },
    {
      "key": "c2",
      "text": "Данные используют, чтобы выделить коллекторы в разрезе и оценить характер их насыщения.",
      "kind": "observation",
      "unit_id": "u-090-46f1de",
      "page": 90,
      "quote": "выделения и оценки характера насыщения коллекторов в разрезе",
      "numbers": [],
      "question": null
    },
    {
      "key": "c3",
      "text": "Данные используют, чтобы определить эффективную толщину, пористость и насыщение нефтью или газом.",
      "kind": "observation",
      "unit_id": "u-090-46f1de",
      "page": 90,
      "quote": "определения эффективной толщины, коэффициентов пористости и нефтегазонасыщения",
      "numbers": [],
      "question": null
    },
    {
      "key": "c4",
      "text": "Данные также используют, чтобы оценить проницаемость и глинистость продуктивных коллекторов.",
      "kind": "observation",
      "unit_id": "u-090-46f1de",
      "page": 90,
      "quote": "оценки коэффициентов проницаемости и глинистости продуктивных коллекторов",
      "numbers": [],
      "question": null
    },
    {
      "key": "c5",
      "text": "По геофизическим данным устанавливают, как движутся водонефтяной (ВНК) и газожидкостный (ГЖК) контакты при разработке месторождения.",
      "kind": "observation",
      "unit_id": "u-090-9d403a",
      "page": 90,
      "quote": "по геофизическим материалам устанавливается характер продвижения водонефтяного (ВНК) и газожидкостного (ГЖК) контактов в процессе разработки месторождения",
      "numbers": [],
      "question": null
    },
    {
      "key": "c6",
      "text": "Задача о контактах добавляется к списку задач именно для эксплуатационных скважин.",
      "kind": "observation",
      "unit_id": "u-090-9d403a",
      "page": 90,
      "quote": "По данным, полученным в эксплуатационных скважинах, кроме указанных задач",
      "numbers": [],
      "question": null
    }
  ],
  "mechanism": [
    {
      "text": "Книга здесь не объясняет физику приборов. Она перечисляет, для каких выводов нужны данные скважин.",
      "claims": ["c1"],
      "hypothesis": false
    },
    {
      "text": "Пласт — это порода с порами. Поры могут быть заняты нефтью, газом или водой, поэтому насыщение бывает разным.",
      "claims": [],
      "hypothesis": true
    },
    {
      "text": "Один и тот же набор данных даёт разные ответы, потому что каждый вывод опирается на свою часть информации.",
      "claims": ["c1", "c2", "c3", "c4"],
      "hypothesis": true
    },
    {
      "text": "Поисковые скважины ищут новые месторождения, разведочные изучают найденное, эксплуатационные добывают нефть или газ.",
      "claims": ["c1"],
      "hypothesis": true
    }
  ],
  "practice": [
    {
      "text": "Специалист сначала формулирует вопрос к данным: нужен ли разрез, насыщение, толщина, пористость, проницаемость или глинистость.",
      "claims": ["c1", "c2", "c3", "c4"],
      "hypothesis": true
    },
    {
      "text": "Для эксплуатационных скважин в список вопросов добавляется продвижение ВНК и ГЖК.",
      "claims": ["c5", "c6"],
      "hypothesis": false
    },
    {
      "text": "Каждый вывод требует отдельного разбора кривых, а не одного взгляда на диаграмму.",
      "claims": [],
      "hypothesis": true
    }
  ],
  "nuances": [
    {
      "text": "Книга задаёт пористость и проницаемость как разные коэффициенты. Их нельзя считать одной и той же величиной.",
      "claims": ["c3", "c4"],
      "hypothesis": false
    },
    {
      "text": "Ответ о ВНК и ГЖК книга связывает с эксплуатационными скважинами, а не со всеми скважинами.",
      "claims": ["c6"],
      "hypothesis": false
    },
    {
      "text": "В этом узле ГЖК — газожидкостный контакт, как назвал его автор. Другие виды контактов здесь не разбираются.",
      "claims": ["c5"],
      "hypothesis": false
    },
    {
      "text": "Данные ГИС косвенные: сами по себе они не называют породу или флюид. Вывод требует интерпретации.",
      "claims": ["c1"],
      "hypothesis": true
    }
  ],
  "deeper": [
    {
      "title": "Зачем один набор данных на разные задачи",
      "text": "Один комплекс приборов записывает много кривых. Разные выводы берутся из разных сочетаний этих кривых. Это разберут следующие узлы.",
      "claims": [],
      "hypothesis": true
    }
  ],
  "procedure": [],
  "numbers_conditions": [
    {
      "text": "Данные берутся из поисковых, разведочных и эксплуатационных скважин на нефть и газ.",
      "claims": ["c1"]
    },
    {
      "text": "Вопрос о продвижении ВНК и ГЖК ставится при разработке месторождения по данным эксплуатационных скважин.",
      "claims": ["c5", "c6"]
    }
  ],
  "terms_defined": [
    {
      "term": "литологический разрез",
      "term_en": "lithological section",
      "abbr": "",
      "definition": "Описание пород по глубине скважины: состав и строение каждого слоя. Его строят по данным ГИС.",
      "claims": ["c1"]
    },
    {
      "term": "характер насыщения",
      "term_en": "fluid saturation type",
      "abbr": "",
      "definition": "Какая жидкость или газ заполняет поры коллектора: нефть, газ или вода. Определяют для каждого коллектора.",
      "claims": ["c2"]
    },
    {
      "term": "эффективная толщина",
      "term_en": "effective thickness",
      "abbr": "",
      "definition": "Толщина той части пласта, которая действительно работает как коллектор. Порядок расчёта разберём позже.",
      "claims": ["c3"]
    },
    {
      "term": "глинистость",
      "term_en": "clay content",
      "abbr": "",
      "definition": "Доля глинистого материала в породе. Глина меняет свойства коллектора и показания приборов.",
      "claims": ["c4"]
    },
    {
      "term": "продуктивный коллектор",
      "term_en": "productive reservoir",
      "abbr": "",
      "definition": "Коллектор, из которого можно получить нефть или газ. Именно такие коллекторы оценивают на продуктивность.",
      "claims": ["c4"]
    },
    {
      "term": "водонефтяной контакт (ВНК)",
      "term_en": "oil-water contact (OWC)",
      "abbr": "ВНК",
      "definition": "Граница в пласте между нефтью сверху и водой снизу. При разработке она смещается.",
      "claims": ["c5"]
    },
    {
      "term": "газожидкостный контакт (ГЖК)",
      "term_en": "gas-liquid contact (GLC)",
      "abbr": "ГЖК",
      "definition": "Граница в пласте между газом и жидкостью. Книга использует его при оценке продвижения контакта в ходе разработки.",
      "claims": ["c5"]
    }
  ],
